steps.code:
mutation {
  companyLocationAssignAddress(
    locationId: "gid://shopify/CompanyLocation/1",
    address: { address1: "Rua Exemplo, 123", city: "São Paulo", countryCode: BR },
    addressTypeInput: SHIPPING
  ) { userErrors { field message } }
}

mutation {
  catalogCreate(input: {
    companyLocationIds: ["gid://shopify/CompanyLocation/1"],
    title: "Catálogo Loja Parceira",
    status: ACTIVE
  }) {
    catalog { id }
    userErrors { field message }
  }
}

mutation {
  draftOrderCreate(input: {
    lineItems: [{ variantId: "gid://shopify/ProductVariant/1", quantity: 10 }],
    purchasingEntity: {
      purchasingCompany: {
        companyLocationId: "gid://shopify/CompanyLocation/1"
      }
    }
  }) { draftOrder { id } userErrors { field message } }
}

mutation {
  draftOrderComplete(id: "gid://shopify/DraftOrder/1") {
    draftOrder { order { id } }
    userErrors { field message }
  }
}

mutation {
  catalogCreate(input: {
    companyLocationIds: ["gid://shopify/CompanyLocation/<id>"],
    title: "Catálogo Parceiro Atacado",
    status: ACTIVE
  }) { catalog { id } }
}
